package com.pratik.imagetap;
import android.content.*;import android.graphics.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PresetArchiveTest {
 Context c;@Before public void setup(){c=RuntimeEnvironment.getApplication();}
 File sample()throws Exception{Bitmap b=Bitmap.createBitmap(24,24,Bitmap.Config.ARGB_8888);b.eraseColor(Color.TRANSPARENT);for(int i=2;i<22;i++)b.setPixel(i,i,Color.WHITE);File f=TargetStore.save(c,b);b.recycle();return f;}
 byte[] exported()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();PresetArchive.exportSlot(c,PresetStore.active(c),out);return out.toByteArray();}
 @Test public void roundTripPreservesPixelsOptionsAndOtherSlots()throws Exception{File original=sample();new TargetOptions(false,1080,new RegionRules.Region(.6f,0,1,.3f,75),"Close ×").save(c,original);PresetStore.rename(c,0,"My game");byte[] png=java.nio.file.Files.readAllBytes(original.toPath()),zip=exported();try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(zip))){assertEquals("My game",s.name);assertEquals(1,s.count());PresetArchive.install(c,s,1,PresetStore.folder(c,1).getName());assertEquals(1,PresetStore.active(c));File imported=TargetStore.files(c).get(0);assertArrayEquals(png,java.nio.file.Files.readAllBytes(imported.toPath()));TargetOptions o=TargetOptions.load(c,imported);assertFalse(o.enabled);assertEquals(1080,o.sourceWidth);assertEquals("Close ×",o.name);assertEquals(.6f,o.area.left,0);assertTrue(original.exists());assertEquals(0,PresetStore.files(PresetStore.folder(c,2)).size());}assertEquals(1,TargetStore.files(c).size());}
 @Test public void cancelDeletesStagingButKeepsSavedPreset()throws Exception{File original=sample();File folder;try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(exported()))){folder=s.folder;}assertFalse(folder.exists());assertTrue(original.exists());}
 @Test public void changedDestinationCannotBeOverwritten()throws Exception{sample();try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(exported()))){String old=PresetStore.folder(c,1).getName();PresetStore.copyCurrent(c,1,"Updated slot");try{PresetArchive.install(c,s,1,old);fail();}catch(IOException expected){}assertEquals("Updated slot",PresetStore.name(c,1));assertEquals(0,PresetStore.active(c));}}
 @Test public void rejectsPathTraversalWithoutChangingPreset()throws Exception{File original=sample();expectRejected(zip(Map.of("../escape.png",new byte[]{1})));assertTrue(original.exists());assertFalse(new File(c.getFilesDir(),"escape.png").exists());}
 @Test public void rejectsInvalidPngMissingAndFutureManifest()throws Exception{sample();byte[] original=exported();Map<String,byte[]> files=entries(original);files.put("images/0000.png",new byte[]{1,2,3});expectRejected(zip(files));files=entries(original);files.remove("manifest.json");expectRejected(zip(files));files=entries(original);JSONObject j=new JSONObject(new String(files.get("manifest.json"),StandardCharsets.UTF_8));j.put("version",99);files.put("manifest.json",j.toString().getBytes(StandardCharsets.UTF_8));expectRejected(zip(files));}
 @Test public void invalidOptionsDoNotTouchDestination()throws Exception{sample();Map<String,byte[]> files=entries(exported());JSONObject j=new JSONObject(new String(files.get("manifest.json"),StandardCharsets.UTF_8));j.getJSONArray("images").getJSONObject(0).put("sourceWidth",-1);files.put("manifest.json",j.toString().getBytes(StandardCharsets.UTF_8));String before=PresetStore.folder(c,0).getName();expectRejected(zip(files));assertEquals(before,PresetStore.folder(c,0).getName());}
 @Test public void rejectsOversizedCompressedManifest()throws Exception{expectRejected(zip(Map.of("manifest.json",new byte[PresetArchive.MAX_MANIFEST+1])));}
 @Test public void truncatedPngIsRejected()throws Exception{sample();Map<String,byte[]> files=entries(exported());byte[] png=files.get("images/0000.png");files.put("images/0000.png",Arrays.copyOf(png,png.length-12));expectRejected(zip(files));}
 @Test public void emptyPresetIsPortable()throws Exception{try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(exported()))){assertEquals(0,s.count());PresetArchive.install(c,s,2,PresetStore.folder(c,2).getName());assertEquals(2,PresetStore.active(c));assertTrue(TargetStore.files(c).isEmpty());}}
 void expectRejected(byte[] bytes)throws Exception{int before=PresetStore.files(PresetStore.folder(c,0)).size();try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(bytes))){fail("Expected invalid import");}catch(IOException expected){}assertEquals(before,PresetStore.files(PresetStore.folder(c,0)).size());File[] junk=c.getFilesDir().listFiles((d,n)->n.startsWith("preset-import-"));assertEquals(0,junk.length);}
 static byte[] zip(Map<String,byte[]> files)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(Map.Entry<String,byte[]> e:files.entrySet()){zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue());zip.closeEntry();}}return out.toByteArray();}
 static Map<String,byte[]> entries(byte[] bytes)throws Exception{Map<String,byte[]> files=new LinkedHashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;while((e=zip.getNextEntry())!=null){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=zip.read(b))!=-1)out.write(b,0,n);files.put(e.getName(),out.toByteArray());}}return files;}
}
